"""Crystallized Verified Skill Library (L_tools) - Auto-Generated by Loop 2."""

def kahan_max_subarray(nums: list[float]) -> float:
    cur = best = float(nums[0])
    for v in nums[1:]:
        fv = float(v)
        cur = max(fv, cur + fv)
        best = max(best, cur)
    return float(best)

def dfa_weighted_transitions(s: str, cost0: int, cost1: int) -> int:
    if s.count('1') % 2 != 0:
        return -1
    return s.count('0') * cost0 + s.count('1') * cost1

def widest_path_capacity(adj: dict, route: list[int]) -> float:
    if len(route) < 2:
        return 0.0
    return float(min(adj[route[i]][route[i+1]] for i in range(len(route) - 1)))

def weighted_mismatch_cost(s1: str, s2: str, weights: list[float]) -> float:
    return float(sum(float(weights[i]) for i in range(len(s1)) if s1[i] != s2[i]))

def count_target_subseq(text: str, pat: str) -> int:
    dp = [1] + [0] * len(pat)
    for ch in text:
        for j in range(len(pat) - 1, -1, -1):
            if ch == pat[j]:
                dp[j + 1] += dp[j]
    return dp[len(pat)]


def stabilized_route_margin(series: list[float], adj: dict, route: list[int], scale: float) -> float:
    return (kahan_max_subarray(series) + widest_path_capacity(adj, route)) * float(scale)


def autonomous_corridor_utility(series: list[float], adj: dict, route: list[int], log: str, sig: str, scale: float) -> float:
    return stabilized_route_margin(series, adj, route, scale) * count_target_subseq(log, sig)


def dfa_penalized_divergence(token: str, c0: int, c1: int, s1: str, s2: str, weights: list[float], scale: float) -> float:
    return (dfa_weighted_transitions(token, c0, c1) - weighted_mismatch_cost(s1, s2, weights)) * float(scale)


def adaptive_horizon_flux(series: list[float], s1: str, s2: str, weights: list[float], scale: float) -> float:
    return (kahan_max_subarray(series) - weighted_mismatch_cost(s1, s2, weights)) * scale
